typedef float rational_t;
typedef float time_value_t;

template <class T>
class vector
{
public:
  typedef const T* const_iterator;

  const_iterator begin() const { return start; }
  const_iterator end() const { return finish; }

private:
  T* start;
  T* finish;
  T* end_of_storage;
};

class vector3d
{
public:
  vector3d operator*(rational_t) const;
};

extern const vector3d YVEC;
extern rational_t g_gravity;
extern rational_t g_time_dilation;

class physical_interface
{
public:
  enum force_type
  {
    CONTINUOUS=0,
    INSTANT
  };

  bool is_enabled() const;
  bool is_gravity() const;
  rational_t get_mass() const;
  rational_t get_gravity_multiplier() const;
  virtual void apply_force_increment(const vector3d&, force_type);
};

class time_interface
{
public:
  rational_t calc_time_dilation();
};

class entity
{
public:
  bool has_physical_ifc() const;
  physical_interface* physical_ifc() const;
  virtual bool is_stationary() const;
  bool has_time_ifc() const;
  time_interface* time_ifc() const;
};

class world_dynamics_system
{
public:
  vector<entity *> const& get_active_entities() const;
};

extern world_dynamics_system* g_world_ptr;

class os_developer_options
{
public:
  static os_developer_options* inst();
  bool get_gravity_enabled() const;
};

class force_generator
{
public:
  virtual ~force_generator();
  virtual void frame_advance(time_value_t)=0;
};

class gravity_generator: public force_generator
{
public:
  virtual void frame_advance(time_value_t time_inc);
};

#define ENTITY_TIME_DILATION(e)           (e->has_time_ifc() ? e->time_ifc()->calc_time_dilation() : g_time_dilation)
#define CALC_ENTITY_TIME_DILATION(a, e)   (a*ENTITY_TIME_DILATION(e))

void gravity_generator::frame_advance(time_value_t time_inc)
{
  vector<entity *>::const_iterator ei;
	if(os_developer_options::inst()->get_gravity_enabled()){
//		for(int i = 0; i < g_world_ptr->get_num_entities(); i++){
//			if(g_world_ptr->is_entity_valid(i)){
  for (ei = g_world_ptr->get_active_entities().begin();ei<g_world_ptr->get_active_entities().end();ei++)
    {
    entity *ent = (*ei); //g_world_ptr->get_entity(i);
//    if ( ent && ent->is_flagged(EFLAG_PHYSICS) && ent->is_gravity() && !ent->is_stationary() )
    if ( ent && ent->has_physical_ifc() && ent->physical_ifc()->is_enabled() && ent->physical_ifc()->is_gravity() && !ent->is_stationary() )
      {
/*
#if defined(TARGET_PC)
          if (ent->get_flavor()==ENTITY_ENTITY)
            {
            stringx composite = stringx("Active, non-stationary entity: ") + ent->get_id().get_val();
            error(composite.c_str());
            }
#endif
*/
      vector3d force = YVEC * (-g_gravity * ent->physical_ifc()->get_mass() * (CALC_ENTITY_TIME_DILATION(time_inc, ent)) * ent->physical_ifc()->get_gravity_multiplier());
      ent->physical_ifc()->apply_force_increment(force, physical_interface::CONTINUOUS);
      }
    }
  }
}
